/**
 * A realistic /api/catchup/overview payload: 29 students across every bucket,
 * 8 classes in every recap state, and a reasons feed long enough to page.
 * The E2E classroom on staging has no absences at all, so the Catch-up layout
 * can only be exercised against this. Shape: apps/nexus/src/components/catchup/types.ts.
 */
/* eslint-disable */
const NAMES=['Hari Heera','Nethra Ranjith','Pranava sakthi','Rakshana Rajagopal','Ridhusha Prawin Rajan','Sowmiya Lakshmi Narayanan','Arun','Deepika Venkatesh','Karthikeyan Subramaniam','Meera','Kavin','Priyadharshini Balasubramanian','Sanjay','Harini','Vishnu Prasad','Aishwarya','Gokul','Divya Bharathi','Tharun','Janani','Mohammed Irfan','Swetha','Lokesh','Keerthana','Rahul','Nivetha','Bala','Anitha','Surya'];
const BUCKETS=['run_over','run_over','not_started','behind','in_progress','waiting_on_us','run_over','not_started','all_clear'];
const REASONS=[['sick','Had fever, will watch the recording tonight'],['family',null],['exam','School exam that day'],['other','Network was down in our area for the whole evening, sorry sir'],[null,null]];
const classes=Array.from({length:8},(_,i)=>({id:'cl'+i,title:['Perspective drawing: two point','Basic 3D Shape Composition','Memory drawing, street scene','Aptitude: mental ability set 4','Colour theory and harmony','NATA mock paper review','Building materials quiz','Isometric views practice'][i],scheduled_date:new Date(Date.UTC(2026,8,20-i*3)).toISOString().slice(0,10)}));
function item(i: number, j: number, s: string){const r=REASONS[(i+j)%REASONS.length];const c=classes[(i+j)%classes.length];return {id:`it-${i}-${j}`,scheduled_class_id:c.id,kind:'no_show',status:s==='waiting_on_us'?'pending_teacher':(j===0&&(s==='run_over'||s==='in_progress')?'active':'waiting'),step:'watch',chained:false,due_on:j===0?'2026-09-22':null,overdue:s==='run_over'&&j===0,active:j===0&&(s==='run_over'||s==='in_progress'),days_left:j===0?-2:null,recommended:j===0,reason_code:r[0],reason_note:r[1],reason_submitted_at:r[0]?'2026-09-19T10:00:00Z':null,reason_source:r[0]?'student':null,followup_sent_at:null,caught_up_at:null,excuse_note:null,watched:false,assignments_outstanding:1,assignments_total:1,has_test:true,test_passed:false,excused:false,class:{title:c.title,scheduled_date:c.scheduled_date}};}
const students=NAMES.map((n: string, i: number)=>{const b=BUCKETS[i%BUCKETS.length];const k=b==='all_clear'?0:2+(i%9);const items=b==='all_clear'?[]:Array.from({length:Math.min(k,6)},(_: unknown, j: number)=>item(i,j,b));
return {journey_id:'j'+i,student:{id:'s'+i,name:n,email:n.toLowerCase().replace(/\s+/g,'.')+'@neramclasses.com',phone:'+9190000000'+String(i).padStart(2,'0'),avatar_url:null},bucket:b,openCount:b==='waiting_on_us'||b==='all_clear'?0:k,blockedOnUs:b==='waiting_on_us'?2:0,totals:{total:k,completed:1,blocked:0,pendingTeacher:0},missedTotals:{total:k,completed:1,open:k,overdue:b==='run_over'?1:0,waiting:k},clock:{active:b==='run_over'||b==='in_progress',waiting:k,overdue:b==='run_over',daysLeft:b==='in_progress'?3:-2,stalled:b==='not_started'},pace:{state:b==='behind'?'behind':'on_track',deficit:b==='behind'?3:0,remaining:k},standing:{clearedTotal:i%4,ownOpen:k,lateJoinerOpen:i%3===0?2:0,oldestOpenDays:10+i,lastClearedAt:null,medianDaysToClear:4,chasedAt:i%2?'2026-09-15T10:00:00Z':null,unresponsive:i%3===1},celebration:b==='all_clear'?null:undefined,items};});
const reasons=students.flatMap(s=>s.items.filter(it=>it.reason_code).slice(0,2).map(it=>({...it,student:s.student})));
const tally: Record<string, number> = {};for(const s of students)tally[s.bucket]=(tally[s.bucket]||0)+1;
const byBucket={waiting_on_us:0,run_over:0,not_started:0,behind:0,in_progress:0,all_clear:0,...tally};
const RS=['published','recording_ready','draft','no_recording','published','recording_ready','published','no_recording'];
const classStats=classes.map((c,i)=>({...c,present:18+i,missed:6+i,caughtUp:i,outstanding:5+i,blocked:RS[i]==='no_recording'?3:0,recap_state:RS[i],recap_id:RS[i]==='draft'||RS[i]==='published'?'rc'+i:null,has_transcript:i%2===0,teams_meeting_id:'m'+i}));
export const catchupOverviewPayload: any ={classroomId:'x',students,classes,classStats,reasons,reasonTally:{sick:8,family:5,exam:6,other:4},completed:[],noRecording:[],pendingRecap:[],celebrationsUnavailable:false,totals:{studentsBehind:16,studentsCatchingUp:26,outstanding:394,clearedThisMonth:49,explained:78,unexplained:228,byBucket,hiddenDormant:6}};
